import csv
from pathlib import Path
ings=list(csv.DictReader(open('/root/ingredient_cost.csv')))
cc={int(r['blister_card_count']):float(r['card_cost_usd']) for r in csv.DictReader(open('/root/card_cost.csv'))}
rr={r['medication']:float(r['reimbursement_per_cycle_180_patients_usd']) for r in csv.DictReader(open('/root/reimbursement.csv'))}
patients=180; fills_28=12; fills_56=6; caps_28=56; caps_56=112
for mode in ['same_card','double_card_if_available_else_double_cost']:
    t28=t56=0
    for r in ings:
        price=float(r['price_per_1000_capsules_usd']); med=r['medication']; b=int(r['blister_card_count'])
        drug28=round((caps_28/1000)*price*patients*fills_28,2); drug56=round((caps_56/1000)*price*patients*fills_56,2)
        pkg28=round(cc[b]*patients*fills_28,2)
        if mode=='same_card': pkg56=round(cc[b]*patients*fills_56,2)
        else: pkg56=round((cc.get(b*2,cc[b]*2))*patients*fills_56,2)
        reimb28=round(rr[med]*fills_28,2); reimb56=round(rr[med]*fills_56,2)
        m28=round(reimb28-drug28-pkg28,2); m56=round(reimb56-drug56-pkg56,2)
        t28+=m28;t56+=m56
    print(mode, round(t28,2), round(t56,2), round(t56-t28,2), abs(round(t56-t28,2)))
